#include <stdio.h>

static long long comb(int n, int k)
{
    if (k < 0 || k > n) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    return comb(n - 1, k - 1) + comb(n - 1, k);
}

int main(void)
{
    int n, k;

    if (scanf("%d%d", &n, &k) != 2) {
        return 0;
    }
    printf("ways: %lld\n", comb(n, k));
    printf("fixed: %lld\n", k == 0 ? 0LL : comb(n - 1, k - 1));
    return 0;
}

#include <stdio.h>

#define MAXN 1005
#define MAXL 24

typedef struct {
    int id;
    char name[MAXL];
} Cell;

static Cell a[MAXN];

int main(void)
{
    int n, m, i, q;
    int lo, hi, mid;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d%23s", &a[i].id, a[i].name);
    }
    scanf("%d", &m);
    for (i = 0; i < m; i++) {
        scanf("%d", &q);
        lo = 0;
        hi = n - 1;
        mid = -1;
        while (lo <= hi) {
            mid = lo + (hi - lo) / 2;
            if (a[mid].id == q) {
                break;
            } else if (a[mid].id < q) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if (lo <= hi) {
            printf("%s\n", a[mid].name);
        } else {
            printf("not found\n");
        }
    }
    return 0;
}

#include <stdio.h>

#define MAXL 1005

int main(void)
{
    char s[MAXL];
    int last[26];
    int i, left = 0, bestLen = 0, bestStart = 0;

    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }
    for (i = 0; i < 26; i++) {
        last[i] = -1;
    }
    for (i = 0; s[i] != '\0' && s[i] != '\n' && s[i] != '\r'; i++) {
        int c = s[i] - 'a';
        if (last[c] >= left) {
            left = last[c] + 1;
        }
        last[c] = i;
        if (i - left + 1 > bestLen) {
            bestLen = i - left + 1;
            bestStart = left;
        }
    }
    printf("longest: %d\n", bestLen);
    printf("segment: %.*s\n", bestLen, s + bestStart);
    return 0;
}

