#include <stdio.h>

#define MAXL 205

int main(void)
{
    char s[MAXL];
    char out[MAXL];
    int i, k = 0;
    int seen[26] = {0};
    int distinct = 0;
    char ch;

    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }
    for (i = 0; s[i] != '\0' && s[i] != '\n' && s[i] != '\r'; i++) {
        ch = s[i];
        if (ch >= 'A' && ch <= 'Z') {
            ch = (char)(ch - 'A' + 'a');
        }
        if (ch >= 'a' && ch <= 'z') {
            out[k] = ch;
            k++;
            if (seen[ch - 'a'] == 0) {
                seen[ch - 'a'] = 1;
                distinct++;
            }
        }
    }
    out[k] = '\0';
    printf("letters: %s\n", out);
    printf("distinct: %d\n", distinct);
    return 0;
}

