int main(void)
{
    char s[MAXL];
    char *p;
    const char *best = NULL;
    int bestLen = 0;

    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }
    p = s;
    while (*p != '\0' && *p != '\n' && *p != '\r') {
        if (*p >= '0' && *p <= '9') {
            char *start = p;
            while (*p >= '0' && *p <= '9') {
                p++;
            }
            if ((int)(p - start) > bestLen) {
                bestLen = (int)(p - start);
                best = start;
            }
        } else {
            p++;
        }
    }
    if (bestLen == 0) {
        printf("none\n");
    } else {
        printf("code: %.*s\n", bestLen, best);
        printf("len: %d\n", bestLen);
    }
    return 0;
}

