#include <stdio.h>

#define MAXN 105
#define LIMIT 30

typedef struct {
    int id;
    char book[24];
    int days;
} Rec;

static Rec r[MAXN];

int main(void)
{
    int n, i, k = 0;
    int worst = 0, hasWorst = 0;
    double total = 0.0, best = 0.0, fine;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d%23s%d", &r[i].id, r[i].book, &r[i].days);
    }
    for (i = 0; i < n; i++) {
        if (r[i].days > LIMIT) {
            fine = (double)(r[i].days - LIMIT) * 0.5;
            k++;
            total += fine;
            if (!hasWorst || fine > best || (fine == best && r[i].id < worst)) {
                best = fine;
                worst = r[i].id;
                hasWorst = 1;
            }
        }
    }
    printf("overdue: %d\n", k);
    printf("total: %.2f\n", total);
    printf("worst: %d\n", worst);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int m, n, i, j;
    int **a;
    int rowsum = 0;
    int best = 0, bestR = 1, bestC = 1;
    int first = 1;

    if (scanf("%d%d", &m, &n) != 2) {
        return 0;
    }
    a = (int **)malloc((size_t)m * sizeof(int *));
    if (a == NULL) {
        return 0;
    }
    for (i = 0; i < m; i++) {
        a[i] = (int *)malloc((size_t)n * sizeof(int));
        if (a[i] == NULL) {
            for (j = 0; j < i; j++) {
                free(a[j]);
            }
            free(a);
            return 0;
        }
    }
    for (i = 0; i < m; i++) {
        int rmax = 0;
        for (j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            if (j == 0 || a[i][j] > rmax) {
                rmax = a[i][j];
            }
            if (first || a[i][j] > best) {
                best = a[i][j];
                bestR = i + 1;
                bestC = j + 1;
                first = 0;
            }
        }
        rowsum += rmax;
    }
    printf("rowmax sum: %d\n", rowsum);
    printf("global max: %d at row %d col %d\n", best, bestR, bestC);
    for (i = 0; i < m; i++) {
        free(a[i]);
    }
    free(a);
    return 0;
}

#include <stdio.h>

#define MAXL 32

static int n;
static char buf[MAXL];
static int total = 0;

static void dfs(int pos, int left, int right)
{
    if (pos == 2 * n) {
        buf[pos] = '\0';
        printf("%s\n", buf);
        total++;
        return;
    }
    if (left < n) {
        buf[pos] = '(';
        dfs(pos + 1, left + 1, right);
    }
    if (right < left) {
        buf[pos] = ')';
        dfs(pos + 1, left, right + 1);
    }
}

int main(void)
{
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    dfs(0, 0, 0);
    printf("total: %d\n", total);
    return 0;
}

#include <stdio.h>

#define MAXS 10005
#define MAXN 15
#define INF 100000000

int main(void)
{
    int n, s, i, j;
    int a[MAXN];
    int dp[MAXS];

    if (scanf("%d%d", &n, &s) != 2) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    for (j = 0; j <= s; j++) {
        dp[j] = INF;
    }
    dp[0] = 0;
    for (i = 0; i < n; i++) {
        for (j = a[i]; j <= s; j++) {
            if (dp[j - a[i]] + 1 < dp[j]) {
                dp[j] = dp[j - a[i]] + 1;
            }
        }
    }
    if (dp[s] >= INF) {
        printf("impossible\n");
    } else {
        printf("min coupons: %d\n", dp[s]);
    }
    return 0;
}
